// end of generated

export type InputBoxWrapperProps = ElementProps<HTMLLabelElement, LabelHTMLAttributes<HTMLLabelElement>> & {
	invisible?: boolean;
	small?: boolean;
	textarea?: boolean;
	endAddonFlush?: boolean;
};

const layoutOf = (small?: boolean, textarea?: boolean, flush?: boolean) => {
	if (small) {
		return 'small';
	}
	if (textarea) {
		return flush ? 'textarea-flush' : 'textarea';
	}
	return flush ? 'flush' : 'default';
};

// The wrapper is a label, so a `Label` inside it renders as a span
const InputBoxWrapper = ({ ref, small, textarea, endAddonFlush, className, children, ...props }: InputBoxWrapperProps) => (
	<LabelContext.Provider value={true}>
		<InputBoxWrapperContext.Provider value={true}>
			<InputBoxWrapperFrame
				render={
					<Box
						is='label'
						animated
						rcx-label
						rcx-input-box__wrapper
						rcx-input-box__wrapper--end-addon-flush={endAddonFlush}
						{...props}
						ref={ref}
					/>
				}
				layout={layoutOf(small, textarea, endAddonFlush)}
				className={className}
			>
				{children}
			</InputBoxWrapperFrame>
		</InputBoxWrapperContext.Provider>
	</LabelContext.Provider>
);

export default InputBoxWrapper;
